-- This header is used by the dbupdate tool.
-- The TARGET property is used to indicate which database the script is
-- intended to be executed on. The value can be either 'Surveillance' or
-- 'SurveillanceLog' without the quotes.
-- The SUPPORTS_TRANSACTION property specifies if the scripts supports
-- running in multi-statement transaction or if it should be running
-- using implicit transactions
-- =========================================================================
-- TARGET: Surveillance
-- SUPPORTS_TRANSACTION: FALSE
-- =========================================================================

-- Enable TRUSTWORTHY to allow load of 'Unsafe' assembly
-- This is required by the "C18NDigest" user-defined function
ALTER DATABASE [{DatabaseName}] SET TRUSTWORTHY ON
GO

-- Enable CLR
EXEC sp_configure 'clr enabled' , '1';
RECONFIGURE;
GO

-- Create SqlTypes Assembly
IF NOT EXISTS (SELECT * FROM sys.assemblies WHERE name = 'VideoOS.SqlServer.SqlTypes')
CREATE ASSEMBLY [VideoOS.SqlServer.SqlTypes]
	AUTHORIZATION [dbo]
	FROM 
	WITH PERMISSION_SET = UNSAFE;
GO

-- Create external user-defined functions
IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[C18NDigest]') AND [type] = 'FS')
DROP FUNCTION [dbo].[C18NDigest]
GO

CREATE FUNCTION [C18NDigest](@xmlDoc XML)
RETURNS NVARCHAR(4000)
AS
 EXTERNAL NAME [VideoOS.SqlServer.SqlTypes].[UserDefinedFunctions].[C18NDigest]
GO

-- Disable CLR
EXEC sp_configure 'clr enabled' , '0';
RECONFIGURE;
